gaYX(){return"\ube0c\ub77c\uc6b0\uc800 \uc601\uc0c1 \ubd84\uc11d\uae30\ub97c \uc2dc\uc791\ud558\uc9c0 \ubabb\ud588\uc5b4\uc694. \ud398\uc774\uc9c0\ub97c \uc0c8\ub85c\uace0\uce68\ud55c \ub4a4 \ub2e4\uc2dc \uc2dc\ub3c4\ud574 \uc8fc\uc138\uc694."},
gaYY(){return"\uc774 \ube0c\ub77c\uc6b0\uc800\uc5d0\uc11c \uc120\ud0dd\ud55c \uc601\uc0c1\uc744 \uc77d\uc9c0 \ubabb\ud588\uc5b4\uc694. MP4 \ub610\ub294 MOV \ud30c\uc77c\ub85c \ub2e4\uc2dc \uc2dc\ub3c4\ud574 \uc8fc\uc138\uc694."},
gaYQ(){return"\uc120\ud0dd\ud55c \uc601\uc0c1 \ud30c\uc77c\uc744 \ucc3e\uc9c0 \ubabb\ud588\uc5b4\uc694."},
gaYW(){return"\uc601\uc0c1\uc774 \ub108\ubb34 \uc9e7\uc544\uc694. \uba87 \uac78\uc74c \uc774\uc0c1 \ub2ec\ub9ac\ub294 \uc7a5\uba74\uc744 \ucc0d\uc5b4 \uc8fc\uc138\uc694."},
gaYV(){return"\uc601\uc0c1\uc774 \ub108\ubb34 \uae38\uc5b4\uc694. 60\ucd08 \uc774\ud558\ub85c \uc798\ub77c\uc11c \ub2e4\uc2dc \uc2dc\ub3c4\ud574 \uc8fc\uc138\uc694."},
